-- The two checklists published on 2026-10-05: the first week after a move
-- (Transitions) and a birthday that lands hard (Milestones).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-05`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-first-week-in-a-new-place', 'The First Week in a New Place', 'For the days after a move, when the boxes are down but nothing feels like yours yet. It helps you make one room livable, learn the streets around you, and get a few ordinary routines going before homesickness sets in.', 'Transitions', '["Finish one room before opening another box — one done space is somewhere to retreat to.", "Make the bed properly on the first night — sleep is harder everywhere else in a new place.", "Walk ten minutes in each direction from the door — streets stop being strange once you have used them.", "Find the nearest grocery store and go once — the first errand turns an address into a neighborhood.", "Put up two things that were on your old walls — familiar objects settle a room faster than new ones.", "Message one person back home with a photo — being seen here helps here feel real.", "Keep one routine exactly as it was — the same coffee or the same walk steadies the rest.", "Say out loud that missing the old place is fine — homesickness is not a sign you chose wrong."]'::jsonb, 'as needed', array['Life Transitions', 'Loneliness']::text[], 1, '2026-10-05T16:00:00+00:00'::timestamptz),
  ('when-your-birthday-lands-hard', 'When Your Birthday Lands Hard', 'For the birthday that brings more dread than celebration, whether it is the number, who is missing, or the gap between the year you wanted and the one you had. It helps you take the day back on your own terms.', 'Milestones', '["Decide a week ahead what the day will hold — a plan you made beats a day that happens to you.", "Tell one person what you actually want from it — people guess badly and mean well.", "Turn off the notifications if the messages sting — you can read them later, all at once.", "Write down three things this year held — a hard year is rarely an empty one.", "Do one thing you would want on an ordinary day — pleasure counts even when the date is loaded.", "Name who is missing from the table out loud — an absence nobody mentions takes up more room.", "Skip the comparison to where you thought you would be — that measure was invented, the day is real.", "Let the day end early if it needs to — a short birthday is allowed."]'::jsonb, 'as needed', array['Self-Compassion', 'Loneliness']::text[], 1, '2026-10-05T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
